# TODO: refactor this mess into a Config dataclass
DEFAULT_HOST = 'localhost'
DEFAULT_PORT = 8080
DEFAULT_WORKERS = 4
DEFAULT_TIMEOUT = 30
MAX_WORKERS = 64
MIN_PORT = 1024
MAX_PORT = 65535

_config = {}

def init(host=DEFAULT_HOST, port=DEFAULT_PORT, workers=DEFAULT_WORKERS, timeout=DEFAULT_TIMEOUT):
    if port < 1024 or port > 65535:
        raise ValueError(f'port must be 1024-65535, got {port}')
    if workers < 1 or workers > 64:
        raise ValueError(f'workers must be 1-64, got {workers}')
    if timeout < 1:
        raise ValueError(f'timeout must be >= 1, got {timeout}')
    _config['host'] = host
    _config['port'] = port
    _config['workers'] = workers
    _config['timeout'] = timeout

def get_host(): return _config.get('host', DEFAULT_HOST)
def get_port(): return _config.get('port', DEFAULT_PORT)
def get_workers(): return _config.get('workers', DEFAULT_WORKERS)
def get_timeout(): return _config.get('timeout', DEFAULT_TIMEOUT)

def reset():
    _config.clear()
